#include <cstdint>
#include <cstdio>
#include <map>
#include <string>
#include <utility>

using NTSTATUS = std::int32_t;

namespace
{
    const std::map<std::uint32_t, std::pair<const char*, std::uint32_t>>& table()
    {
        static const std::map<std::uint32_t, std::pair<const char*, std::uint32_t>> t{
            { 0x00000000u, { "STATUS_SUCCESS", 0 } }, { 0x00000103u, { "STATUS_PENDING", 997 } },
            { 0x80000005u, { "STATUS_BUFFER_OVERFLOW", 234 } }, { 0xC0000002u, { "STATUS_NOT_IMPLEMENTED", 1 } },
            { 0xC000000Du, { "STATUS_INVALID_PARAMETER", 87 } }, { 0xC0000010u, { "STATUS_INVALID_DEVICE_REQUEST", 1 } },
            { 0xC0000022u, { "STATUS_ACCESS_DENIED", 5 } }, { 0xC0000023u, { "STATUS_BUFFER_TOO_SMALL", 122 } },
            { 0xC000009Au, { "STATUS_INSUFFICIENT_RESOURCES", 1450 } } };
        return t;
    }
}

bool ntSuccess(NTSTATUS s) { return s >= 0; }

std::string severity(NTSTATUS s)
{
    switch (static_cast<std::uint32_t>(s) >> 30)
    {
    case 0: return "success";
    case 1: return "informational";
    case 2: return "warning";
    default: return "error";
    }
}

std::string statusName(NTSTATUS s)
{
    const auto it{ table().find(static_cast<std::uint32_t>(s)) };
    if (it != table().end()) return it->second.first;
    char buffer[16];
    std::snprintf(buffer, sizeof(buffer), "0x%08X", static_cast<unsigned>(static_cast<std::uint32_t>(s)));
    return buffer;
}

std::uint32_t toWin32Error(NTSTATUS s)
{
    const auto it{ table().find(static_cast<std::uint32_t>(s)) };
    return it != table().end() ? it->second.second : 317;
}

unitTests:
const NTSTATUS denied = static_cast<NTSTATUS>(0xC0000022u), overflow = static_cast<NTSTATUS>(0x80000005u);
TEST("success or not") { CHECK(ntSuccess(0)); CHECK(ntSuccess(0x103)); CHECK(!ntSuccess(denied)); CHECK(!ntSuccess(overflow)); CHECK(ntSuccess(0x40000000)); }
TEST("severity") { CHECK_EQ(severity(0), std::string("success")); CHECK_EQ(severity(0x40000001), std::string("informational")); CHECK_EQ(severity(overflow), std::string("warning")); CHECK_EQ(severity(denied), std::string("error")); }
TEST("names") { CHECK_EQ(statusName(denied), std::string("STATUS_ACCESS_DENIED")); CHECK_EQ(statusName(0x103), std::string("STATUS_PENDING")); CHECK_EQ(statusName(static_cast<NTSTATUS>(0xC0000135u)), std::string("0xC0000135")); }
TEST("as GetLastError sees it") { CHECK_EQ(toWin32Error(denied), 5u); CHECK_EQ(toWin32Error(static_cast<NTSTATUS>(0xC0000023u)), 122u); CHECK_EQ(toWin32Error(0), 0u); CHECK_EQ(toWin32Error(static_cast<NTSTATUS>(0xC0000135u)), 317u); }

